/* DSY1102 · Cápsula del Tiempo FX · Entrega 06 · R00–R05 (R05 con evidencias docentes) */
const img=(file,title)=>`<figure class="picture"><img src="assets/${file}" alt="Captura real de IntelliJ: ${title}" loading="eager"><div class="fallback"><strong>Captura disponible en el paquete de clase</strong><span>${title}</span><small>Revisa la ruta assets/${file}</small></div><figcaption>CAPTURA REAL · ${title} · Clic para ampliar</figcaption></figure>`;
const card=(n,title,desc,tone='')=>`<div class="item-card"><span class="number ${tone}">${n}</span><div><div class="item-title">${title}</div><div class="item-desc">${desc}</div></div></div>`;
const code=(name,source)=>`<div class="codebox"><div class="codehead"><span>${name}</span><button class="copy-code" data-copy="1">Copiar código</button></div><pre><code>${escapeHtml(source)}</code></pre></div>`;
function escapeHtml(s){return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');}

const slides=[
{section:'PORTADA',title:'Cápsula del Tiempo FX',content:`<div class="hero-body"><div class="capsule-tag">CLASE CONSOLIDADA · UNIDAD 2 · DESDE CERO</div><h1>De una ventana vacía<br>a una <span class="accent">app que recuerda.</span></h1><p class="lead">JavaFX → FXML → MVC → DAO → JSON.<br>Una necesidad nueva. Una solución nueva. Un resultado comprobable.</p><div class="hero-badges"><span>DSY1102</span><span>Java 21 + Maven</span><span>2 bloques · 40 min</span></div></div><div class="hero-constellation">◉</div>`,notes:'Presentar la clase como reconstrucción de semanas 9–11. No atribuir ejecución ni validación a fases todavía no realizadas. Hoy el primer checkpoint sí está respaldado por capturas reales.'},
{section:'CONTRATO DE CLASE',title:'La regla: primero aparece el problema',content:`<h2>Hoy no vamos a <span class="accent">copiar una arquitectura.</span></h2><p class="lead">Vamos a descubrir por qué cada pieza es necesaria, a medida que nuestra aplicación evoluciona.</p><div class="scalable-list">${card('1','Planteamos','Un requerimiento pequeño, observable.')}${card('2','Implementamos','Código completo cuando la herramienta es nueva.')}${card('3','Comprobamos','Resultado, error y causa cuando algo falla.')}</div><div class="important">Un avance no está terminado porque el código se ve bonito: está terminado cuando funciona y podemos explicar por qué.</div>`,notes:'Conectar con EV1: claridad constante de requisitos, asistencia variable en implementación. El proyecto se construirá una sola vez durante la clase, no una práctica nueva por semana.'},
{section:'MAPA DE APRENDIZAJE',title:'¿Hacia dónde vamos?',content:`<h2>Una misma app. <span class="accent">Nuevas necesidades.</span></h2><div class="scalable-list">${card('0','Arrancar','Abrir una ventana con JavaFX.')}${card('1','Representar','Un mensaje con autor, texto y horizonte temporal.')}${card('2','Mostrar','Presentar mensajes mediante TableView y ObservableList.')}${card('3','Interactuar','Formulario, navegación, Controller, validaciones.')}${card('4','Separar','Modelo, vista, controlador, servicio y contrato DAO.')}${card('5','Persistir','Guardar y recuperar JSON sin perder los mensajes.')}</div><div class="screenshot-note">Tenemos evidencia real de <b>R00 a R03</b>: la tabla muestra mensajes y el formulario permite agregar otros, rechazando campos vacíos. R04 está validado; R05 y R06 están pendientes.</div>`,notes:'No introducir todos los requerimientos como exigencias desde el inicio: el mapa es para orientar, cada momento revela su nueva necesidad. Roadmap editorial, no compromete 80 min exactos si falla la instalación.'},
{section:'REQUERIMIENTO 0',title:'R00 · Queremos abrir la cápsula',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">NECESIDAD DEL USUARIO</div><h2>«Quiero abrir mi cápsula del tiempo».</h2><p class="copy">Todavía no hay mensajes ni almacenamiento. Para este primer incremento basta con que aparezca una ventana.</p>${card('RF','Funcional','Al iniciar la aplicación, aparece la ventana de JavaFX.')}${card('RT','Técnico','Usar Java 21, Maven, JavaFX Controls y FXML.','green')}</div><div class="stack middle"><div class="panel"><div class="eyebrow">CRITERIO DE ACEPTACIÓN</div><h3>Una ventana que funciona</h3><p class="copy" style="margin-top:13px">Ejecutar <code>Launcher</code> y observar una ventana real sin error de compilación ni excepción.</p></div><div class="important">No necesitamos DAO, TableView ni JSON todavía.</div></div></div>`,notes:'Preguntar: ¿qué pieza de arquitectura exigimos ahora? Ninguna. Solo entorno, arranque y ventana.'},
{section:'INTELLIJ / CONFIGURACIÓN',title:'Crear el proyecto',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN GUIADA · 01</div><h2>JavaFX + Maven + <span class="accent">JDK 21</span></h2>${card('1','New Project → JavaFX','Java como lenguaje y Maven como sistema de construcción.')}${card('2','Group y Artifact','Grupo: cl.duoc.dsy1102 · Artifact: time-capsule.')}${card('3','SDK','Seleccionamos JDK 21 (WSL en la captura docente).')}</div>${img('01-crear-proyecto.webp','Asistente de nuevo proyecto JavaFX')}</div>`,notes:'Esta captura fue tomada en WSL con Java 21.0.11. El camino general aplica también a Windows. No confundir la versión del JDK instalado con la versión de compilación del proyecto.'},
{section:'INTELLIJ / DEPENDENCIAS',title:'Menos dependencias, menos distracciones',content:`<div class="grid2 tall-image"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN GUIADA · 02</div><h2>¿Qué debemos agregar ahora?</h2><p class="lead"><span class="accent-green">Nada adicional.</span> El generador JavaFX ya nos deja iniciar.</p><div class="panel"><h3>La pantalla «Additional libraries»</h3><p class="copy" style="margin-top:12px">BootstrapFX, ControlsFX y similares pueden ser útiles, pero no resuelven nuestro primer requerimiento.</p></div><div class="screenshot-note">Reutilizamos la configuración estándar. Jackson llegará cuando exista la necesidad de guardar.</div></div>${img('02-bibliotecas-opcionales.webp','Selector de bibliotecas adicionales sin marcar')}</div>`,notes:'Explicar que no agregar todo desde el principio mantiene visible la relación requerimiento-dependencia.'},
{section:'EL ARRANQUE',title:'¿Quién abre la ventana?',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">TOQUE TEÓRICO</div><h2>Launcher → <span class="accent">Application</span></h2>${code('Launcher.java',`package cl.duoc.dsy1102.timecapsule;\n\nimport javafx.application.Application;\n\npublic class Launcher {\n    public static void main(String[] args) {\n        Application.launch(HelloApplication.class, args);\n    }\n}`)}<div class="small">El <b>Launcher</b> inicia el runtime JavaFX. <b>HelloApplication</b> es la aplicación cuya ventana se construye en <code>start(Stage)</code>.</div></div>${img('03-launcher.webp','Launcher real generado por IntelliJ')}</div>`,notes:'Contrastar main de Java con Application.start(Stage). Pedir señalar la instrucción que transfiere el control a JavaFX.'},
{section:'DIAGNÓSTICO 01',title:'¡Aparece un error real!',content:`<h2>«Modules are not supported at <span class="accent" style="color:#ffb279">language level 8</span>»</h2><div class="photo-pair">${img('04-error-modulos.webp','module-info.java marcado en rojo')}${img('05-error-compilacion.webp','Build failed por source 8')}</div><div class="important warning">¿Será que tenemos que usar Java 9? <b>No.</b> Tenemos JDK 21; todavía no sabemos qué configuración está obligando a compilar con Java 8.</div>`,notes:'Mostrar primero el error, no inmediatamente la solución. Pedir hipótesis. module-info.java es una característica disponible desde Java 9. Usaremos Java 21.'},
{section:'DIAGNÓSTICO 02',title:'Distingamos tres configuraciones',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow amber">NO ARREGLAR A CIEGAS</div><h2>JDK, lenguaje y compilación <span class="accent">no son lo mismo.</span></h2>${card('A','SDK del proyecto','El JDK 21 está seleccionado en Project Structure.')}${card('B','Language level del módulo','Puede quedar en Java 8 aunque el SDK sea 21.')}${card('C','pom.xml de Maven','Puede volver a imponer <source>8 y <target>8.','orange')}</div><div class="photo-pair">${img('06-jdk-proyecto.webp','Project SDK 21 en IntelliJ')}${img('07-nivel-modulo.webp','Language level del módulo en Java 8')}</div></div>`,notes:'El primer cambio en IntelliJ hizo desaparecer algunos errores del editor, pero Launcher seguía fallando. Esto evidencia dos vías de compilación distintas y que Maven gobierna la construcción del proyecto.'},
{section:'CAUSA RAÍZ',title:'La causa no estaba en FXML',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow amber">INVESTIGACIÓN</div><h2>Maven seguía compilando con <span style="color:#ffb279">Java 8.</span></h2>${img('09-pom-java8.webp','maven-compiler-plugin con source y target en 8')}</div><div class="stack middle"><div class="eyebrow">ANTES → DESPUÉS</div>${code('pom.xml · configuración anterior',`<configuration>\n    <source>8</source>\n    <target>8</target>\n</configuration>`)}${code('pom.xml · configuración correcta',`<configuration>\n    <release>21</release>\n</configuration>`)}<div class="screenshot-note">Conservamos <b>maven-compiler-plugin 3.13.0</b>, JavaFX y el resto de dependencias. No borramos el POM.</div></div></div>`,notes:'Explicar que release=21 alinea nivel de código y APIs; no cambiar números a ciegas. Mostrar la captura del POM ANTES de corregir, y luego el fragmento de corrección.'},
{section:'CHECKPOINT DE DIAGNÓSTICO',title:'Corregir y validar',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">SECUENCIA DE CORRECCIÓN</div><h2>¿Cómo sabemos que quedó bien?</h2>${card('1','Cambiar <release>21</release>','Modificar la configuración del compilador Maven.')}${card('2','Reload Maven','Sincronizar el modelo del proyecto en IntelliJ.')}${card('3','Rebuild + Run','Recompilar y ejecutar Launcher desde cero.','green')}<div class="checkpoint">✓ Evidencia: la ventana Hello! aparece.</div></div><div class="stack middle">${img('08-error-maven.webp','Consola Maven: error previo source 8')}<div class="screenshot-note">Esta imagen documenta el fallo <b>anterior a la corrección</b>; no se debe presentar como compilación exitosa.</div></div></div>`,notes:'Si en el aula Maven no está en PATH, usar el Maven Tool Window o el wrapper ./mvnw. Para probar en consola: ./mvnw clean compile (WSL/Linux) o mvnw.cmd clean compile (Windows).'},
{section:'CHECKPOINT 00 VALIDADO',title:'¡Nuestra primera ventana!',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">RESULTADO OBSERVADO · 24 OCT 2026</div><h2>¡La cápsula <span class="accent-green">ya despierta!</span></h2><p class="lead">Todavía no hace nada útil... ¡y eso está bien!</p><div class="checkpoint">✓ R00 aceptado: JavaFX inicia y abre una ventana.</div><p class="copy">La ventana «Hello!» es una <b>evidencia real del proyecto</b>, no una imagen generada.</p><div class="important">¿Qué cambió? Ahora podemos desarrollar y probar comportamiento gráfico sobre una base que funciona.</div></div>${img('10-primera-ventana.webp','Ventana Hello! de JavaFX ejecutándose')}</div>`,notes:'Checkpoint real alcanzado por el docente. Captura final de este bloque, en el orden cronológico correcto. No confundir este éxito con toda la aplicación terminada.'},
{section:'PUENTE A R01',title:'Nueva necesidad. Nuevo código.',content:`<div class="hero-body"><div class="eyebrow">PRÓXIMO INCREMENTO · R01</div><h2>«Ahora quiero escribir un mensaje <span class="accent">para mi yo del futuro</span>».</h2><p class="lead">Eso sí requiere datos y reglas: <b>autor, mensaje y horizonte temporal</b>. Aparecerá nuestro primer modelo del dominio.</p><div class="lesson-row"><span class="lesson-chip">Clase MensajeFuturo</span><span class="lesson-chip ghost-chip">Datos primero</span><span class="lesson-chip ghost-chip">Después vista y controles</span></div><div class="important">No necesitamos JSON todavía. Primero construiremos una capacidad que valga la pena guardar.</div></div>`,notes:'Ahora continuamos con el modelo real construido por el docente. Ya hay pruebas y capturas del incremento R01.'}

,{section:'R01 · NECESIDAD',title:'Un mensaje para el futuro',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">REQUERIMIENTO FUNCIONAL · R01</div><h2>«Quiero guardar la idea de un <span class="accent">mensaje futuro</span>».</h2><p class="lead">Primero lo representaremos en Java. La ventana Hello! todavía no necesita cambiar.</p>${card('RF-01','Representar','Cada mensaje tiene autor, texto y plazo en años.')}${card('RT-01','Encapsular','Los atributos son privados; se inicializan por constructor y se consultan por getters.','green')}</div><div class="stack middle"><div class="panel"><div class="eyebrow">PRUEBA DE ACEPTACIÓN</div><h3>Crear un mensaje sin interfaz gráfica</h3><p class="copy" style="margin-top:12px">Instanciar <code>MensajeFuturo</code> y consultar sus tres datos desde un <code>main</code> independiente.</p></div><div class="important">Todavía no se pide TableView, formulario ni JSON: representar ≠ mostrar ≠ persistir.</div></div></div>`,notes:'Requerimientos de este incremento únicamente. Describir que un modelo de dominio no necesita importar JavaFX. No confundir crear un objeto en memoria con guardarlo en disco.'}
,{section:'R01 · TEORÍA APLICADA',title:'¿Qué pertenece al modelo?',content:`<h2>Una clase que representa <span class="accent">algo del dominio</span></h2><div class="scalable-list">${card('1','Estado','autor: String · texto: String · plazoAnios: int')}${card('2','Construcción','El constructor recibe los tres valores al crear el mensaje.')}${card('3','Consulta','Los getters exponen lectura sin abrir los campos privados.')}</div><div class="important">La clase <code>MensajeFuturo</code> no sabe nada de botones, FXML, ventanas o archivos. Esa separación es deliberada.</div><div class="lesson-row"><span class="lesson-chip">private</span><span class="lesson-chip">constructor</span><span class="lesson-chip">getters</span><span class="lesson-chip ghost-chip">todavía sin DAO</span></div>`,notes:'Recordar encapsulación de EA1 y justificar el constructor: un objeto nace con los datos del mensaje. En esta etapa no añadimos validaciones que aún no se han solicitado; el Service las asumirá más adelante.'}
,{section:'R01 · INTELLIJ',title:'Crear el paquete model',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PASO GUIADO · PAQUETES</div><h2>¿Dónde vive la clase?</h2>${card('1','Paquete base','Clic derecho en cl.duoc.dsy1102.timecapsule.')}${card('2','New → Package','Crear el subpaquete model.')}${card('3','Comprobar','La ruta será cl.duoc.dsy1102.timecapsule.model.','green')}<div class="screenshot-note">El paquete model aloja los datos del dominio. Aún no creamos controllers ni DAOs.</div></div><div class="photo-pair">${img('11-crear-paquete.webp','Crear un paquete en IntelliJ')}${img('12-nombre-paquete.webp','Escribir el nombre del nuevo paquete')}</div></div>`,notes:'Capturas reales 12:26:30 y 12:26:43. Si IntelliJ muestra el nombre compacto, es presentación de paquetes, no falta de carpetas.'}
,{section:'R01 · INTELLIJ',title:'Crear MensajeFuturo.java',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">PASO GUIADO · CLASE</div><h2>Una clase concreta,<br>un propósito concreto.</h2>${card('1','Clic en model','New → Java Class.')}${card('2','Nombre exacto','MensajeFuturo (opción Class).')}${card('3','Package','La primera línea debe acabar en .model.','green')}</div><div class="photo-pair">${img('13-crear-clase.webp','Menú para crear nueva clase Java')}${img('14-nombre-clase.webp','Crear la clase MensajeFuturo')}</div></div>`,notes:'Mostrar que New Java Class abre múltiples opciones (Class, Interface, Record). Aquí seleccionamos Class porque es el concepto que queremos reforzar. Imagenes en orden 12:26:55 y 12:27:10.'}
,{section:'R01 · CÓDIGO',title:'Implementar el modelo',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN GUIADA</div><h2>Campos privados<br>y constructor</h2>${code('MensajeFuturo.java · estado y constructor',`package cl.duoc.dsy1102.timecapsule.model;

public class MensajeFuturo {
    private String autor;
    private String texto;
    private int plazoAnios;

    public MensajeFuturo(String autor,
                         String texto, int plazoAnios) {
        this.autor = autor;
        this.texto = texto;
        this.plazoAnios = plazoAnios;
    }
    // A continuación, los getters.
}`)}<div class="small">El constructor define cómo nace el objeto. <code>this.autor</code> distingue el atributo del parámetro.</div></div>${img('16-modelo-implementado.webp','Clase MensajeFuturo con atributos y constructor en IntelliJ')}</div>`,notes:'Código de demostración fraccionado intencionalmente: el archivo final también contiene los tres getters, que aparecen en la siguiente diapositiva. No se requiere interfaz JavaFX para probar el modelo.'}
,{section:'R01 · CÓDIGO',title:'Consultar sin exponer atributos',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">ENCAPSULACIÓN</div><h2>Getters: lectura controlada</h2>${code('Dentro de MensajeFuturo.java',`public String getAutor() {
    return autor;
}

public String getTexto() {
    return texto;
}

public int getPlazoAnios() {
    return plazoAnios;
}`)}<div class="screenshot-note">Los tres métodos van <b>dentro</b> de la clase MensajeFuturo, después del constructor.</div></div><div class="stack middle">${img('15-clase-inicial.webp','Clase creada antes de escribir los atributos')}<div class="important">¿Por qué no colocar <code>System.out.println</code> en el modelo? Porque mostrar datos por consola es responsabilidad de quien lo utiliza, no del mensaje.</div></div></div>`,notes:'Antes/después entre clase vacía y clase con contenido. Aún no se añade setter porque no existe requisito de edición del mensaje.'}
,{section:'R01 · PRUEBA',title:'Probar el modelo sin JavaFX',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PROGRAMA DE COMPROBACIÓN</div><h2>Una clase temporal <span class="accent">PruebaMensaje</span></h2>${code('PruebaMensaje.java · en el paquete base',`MensajeFuturo mensaje = new MensajeFuturo(
    "Valentina",
    "Nunca dejes de perseguir tus sueños.",
    5
);
System.out.println("Autor: " + mensaje.getAutor());
System.out.println("Mensaje: " + mensaje.getTexto());
System.out.println("Leer dentro de: "
    + mensaje.getPlazoAnios() + " años");`)}<div class="small">Agregar el <code>import cl.duoc.dsy1102.timecapsule.model.MensajeFuturo;</code> y ubicar el fragmento dentro de <code>main</code>.</div></div>${img('18-codigo-prueba.webp','Código completo de PruebaMensaje con los getters')}</div>`,notes:'La captura real incluye los métodos de la prueba. Evitar dar a entender que el snippet es un archivo Java completo: es su parte relevante; la clase/main/import se muestra en la imagen.'}
,{section:'R01 · EJECUCIÓN',title:'Ejecutar la prueba correcta',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">CHECKPOINT FUNCIONAL</div><h2>Esta vez, <span class="accent">PruebaMensaje.main()</span></h2><p class="copy">La prueba de nuestro modelo es una aplicación de consola. Por ahora no hace falta volver a ejecutar Launcher ni cambiar el FXML.</p>${card('1','Run','Clic en el triángulo verde junto a main.')}${card('2','Seleccionar','Run “PruebaMensaje.main()”.')}${card('3','Comparar','Verificar autor, texto, plazo y exit code 0.','green')}</div><div class="photo-pair">${img('17-crear-prueba.webp','Crear la clase PruebaMensaje')}${img('19-ejecutar-prueba.webp','Menú Run de PruebaMensaje.main')}</div></div>`,notes:'Capturas reales 12:28:22 y 12:28:44. Esta secuencia es deliberadamente independiente de JavaFX. De esa forma se prueba el dominio antes de conectarlo a la vista.'}
,{section:'R01 · VALIDADO',title:'Nuestro objeto funciona',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CHECKPOINT 01 · VALIDADO</div><h2>Ya existe un <span class="accent-green">mensaje futuro.</span></h2>${code('Salida real · Run',`Autor: Valentina
Mensaje: Nunca dejes de perseguir tus sueños.
Leer dentro de: 5 años

Process finished with exit code 0`)}<div class="checkpoint">✓ R01: clase, instancia y consulta verificadas.</div><div class="small">Éxito en memoria. Todavía no aparecen mensajes en una ventana ni se conservan al cerrar.</div></div><div class="stack middle">${img('20-prueba-validada.webp','Resultado de consola de PruebaMensaje: éxito')}${img('21-arbol-final.webp','Árbol del proyecto con model, MensajeFuturo y PruebaMensaje')}</div></div>`,notes:'Las capturas corresponden al proyecto real compartido por el docente, alrededor de las 12:29. El exit code 0 verifica terminación correcta; la coincidencia de líneas valida el resultado de este caso, no reglas de negocio futuras.'}
,{section:'PUENTE A R02',title:'¿Dónde están mis mensajes?',content:`<div class="hero-body"><div class="eyebrow">PRÓXIMO INCREMENTO · R02</div><h2>«¡Ya puedo crear mensajes! Pero quiero <span class="accent">verlos en la ventana</span>».</h2><p class="lead">Ese nuevo problema justifica conectar JavaFX con una colección de mensajes y presentarlos en una tabla.</p><div class="lesson-row"><span class="lesson-chip">ObservableList</span><span class="lesson-chip">TableView</span><span class="lesson-chip">FXML + Controller</span></div><div class="important">Siguiente checkpoint: mostrar dos mensajes de prueba en una tabla de JavaFX, sin formulario y sin JSON todavía.</div></div>`,notes:'No adelantar la implementación de persistencia: primero mostrar objetos existentes en memoria. Próximo trabajo docente: montar vista de lista, capturar UI real y verificar 2 filas. La captura posterior de R02 certifica que la interfaz terminó funcionando; aquí todavía estamos planteando la nueva necesidad.'}


,{section:'R02 · REQUERIMIENTO',title:'Ya tenemos mensajes: ¿dónde los vemos?',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">RF-02 · NUEVA NECESIDAD</div><h2>«Quiero ver mis mensajes <span class="accent">en una ventana</span>».</h2><p class="lead">El modelo funciona en consola, pero todavía no existe una representación visual de varios mensajes.</p>${card('RF','Mostrar','Presentar al menos dos mensajes en columnas Autor, Mensaje y Leer dentro de.')}${card('RT','Herramientas','FXML, Controller, TableView y ObservableList.','green')}</div><div class="stack middle"><div class="panel"><div class="eyebrow">PRUEBA DE ACEPTACIÓN</div><h3>Dos filas visibles, sin escribirlas en FXML</h3><p class="copy" style="margin-top:12px">Ejecutamos <code>Launcher</code> y la vista muestra Valentina (5 años) y Carlos (10 años).</p></div><div class="important">No hay botones de registro, navegación ni JSON todavía: <b>solo visualización en memoria.</b></div></div></div>`,notes:'Plantear SOLO el requerimiento de mostrar objetos. La introducción del formulario y persistencia se justifica después. La captura docente de la ventana con dos filas es la prueba real.'}
,{section:'R02 · TEORÍA',title:'La vista no es el modelo',content:`<h2>Conectamos piezas con <span class="accent">responsabilidades diferentes.</span></h2><div class="arrow-flow"><div class="flow-node">MensajeFuturo<br><span class="small">datos del dominio</span></div><span class="flow-arrow">→</span><div class="flow-node">ObservableList<br><span class="small">colección observable</span></div><span class="flow-arrow">→</span><div class="flow-node">TableView<br><span class="small">filas y columnas</span></div></div><div class="scalable-list" style="margin-top:28px">${card('1','FXML','Describe qué controles tiene la pantalla.')}${card('2','Controller','Relaciona columnas y datos; prepara la vista.')}${card('3','Modelo','Representa un mensaje; no contiene JavaFX.')}</div><div class="screenshot-note">Al llamar <code>tablaMensajes.setItems(mensajes)</code> conectamos la tabla a la lista, sin copiar manualmente los valores a celdas.</div>`,notes:'Destacar que MVC aquí se construye progresivamente: el Controller aún crea datos de demostración. Refactorizar a Service/DAO llegará en incrementos posteriores, por una necesidad distinta.'}
,{section:'R02 · INTELLIJ',title:'Modificar el FXML',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PASO GUIADO · VISTA</div><h2>De «Hello!» a <span class="accent">tres columnas.</span></h2>${card('1','hello-view.fxml','Abrir desde src/main/resources, paquete timecapsule.')}${card('2','VBox','Título, subtítulo y TableView.')}${card('3','fx:id','tablaMensajes, colAutor, colTexto y colPlazo enlazan con el Controller.','green')}<div class="small">Las dos capturas muestran el FXML y la ruta real de recursos, no el mismo código duplicado en varios lugares.</div></div><div class="stack">${img('22-vista-fxml-y-estructura.webp','Paquete resources y primera declaración de TableView')}${img('23-fxml-tabla-columnas.webp','FXML completo con las columnas de mensajes')}</div></div>`,notes:'Capturas 13:11:31 y 13:11:46. Recordar que fx:id identifica controles para inyectarlos en Controller: escribir el mismo nombre en ambos lados.'}
,{section:'R02 · FXML',title:'Qué pertenece a la vista',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">TEORÍA + IMPLEMENTACIÓN</div><h2>El XML define <span class="accent">estructura visual.</span></h2><p class="copy">Una tabla está vacía hasta que su Controller le entrega una colección y define cómo leer cada columna.</p><div class="important">FXML puede declarar columnas, pero no conoce por sí solo cómo interpretar un <code>MensajeFuturo</code>.</div></div><div class="stack middle">${code('hello-view.fxml · fragmento',`<VBox xmlns:fx="http://javafx.com/fxml/1"
      fx:controller="cl.duoc.dsy1102.timecapsule.HelloController"
      spacing="14" style="-fx-padding: 20;">
    <Label text="Cápsula del Tiempo" />
    <TableView fx:id="tablaMensajes" VBox.vgrow="ALWAYS">
        <columns>
            <TableColumn fx:id="colAutor" text="Autor" />
            <TableColumn fx:id="colTexto" text="Mensaje" />
            <TableColumn fx:id="colPlazo" text="Leer dentro de" />
        </columns>
    </TableView>
</VBox>`)}<div class="small">Fragmento de demostración: conservar declaración XML y líneas <code>&lt;?import ...?&gt;</code> del archivo completo.</div></div></div>`,notes:'Guiar la relación entre fx:controller y la clase Java. Los fx:id deben ser idénticos a los campos @FXML. Evitar teoría adicional sobre Scene Builder; el objetivo es ver una tabla.'}
,{section:'R02 · CONTROLLER',title:'Conectar controles por fx:id',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PASO GUIADO · CONTROLADOR</div><h2><span class="accent">@FXML</span> conecta la vista y Java.</h2>${code('HelloController.java · campos',`@FXML private TableView<MensajeFuturo> tablaMensajes;
@FXML private TableColumn<MensajeFuturo, String> colAutor;
@FXML private TableColumn<MensajeFuturo, String> colTexto;
@FXML private TableColumn<MensajeFuturo, String> colPlazo;

private final ObservableList<MensajeFuturo> mensajes =
        FXCollections.observableArrayList();`)}<div class="small">Se importa el modelo desde <code>...timecapsule.model.MensajeFuturo</code>. La anotación <code>@FXML</code> permite que FXMLLoader conecte cada campo al control declarado en FXML.</div></div>${img('24-controller-observable.webp','Controller real con campos FXML y ObservableList')}</div>`,notes:'Captura real 13:12:35. El proyecto con JavaFX modular ya abre el paquete del Controller para javafx.fxml; mantener module-info sin cambios en este incremento.'}
,{section:'R02 · TABLEVIEW',title:'¿Cómo sabe una columna qué mostrar?',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">CONCEPTO CENTRAL</div><h2>Cada columna <span class="accent">lee una propiedad.</span></h2>${card('1','colAutor','Obtiene getAutor() de cada MensajeFuturo.')}${card('2','colTexto','Obtiene getTexto() de ese mismo objeto.')}${card('3','colPlazo','Transforma el entero del plazo en texto: «5 años».','green')}</div><div class="stack middle">${code('HelloController.initialize() · configuración',`colAutor.setCellValueFactory(c ->
    new ReadOnlyStringWrapper(c.getValue().getAutor())
);
colTexto.setCellValueFactory(c ->
    new ReadOnlyStringWrapper(c.getValue().getTexto())
);
colPlazo.setCellValueFactory(c ->
    new ReadOnlyStringWrapper(
        c.getValue().getPlazoAnios() + " años")
);`)}<div class="small">El valor de la celda se obtiene del objeto completo de esa fila: no debemos escribir filas manualmente en el FXML.</div></div></div>`,notes:'Explicar c.getValue(): es el objeto MensajeFuturo de la fila actual, no un String aislado. ReadOnlyStringWrapper permite que la columna muestre texto. Se usa un wrapper simple porque el modelo es Java puro.'}
,{section:'R02 · OBSERVABLELIST',title:'La tabla observa una colección',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN GUIADA</div><h2>Conectar una vez; <span class="accent">agregar después.</span></h2>${code('Dentro de initialize() · datos de prueba',`tablaMensajes.setItems(mensajes);

mensajes.add(new MensajeFuturo(
    "Valentina", "Nunca dejes de perseguir tus sueños.", 5
));
mensajes.add(new MensajeFuturo(
    "Carlos", "Recuerda de dónde comenzaste.", 10
));`)}<div class="important">Al añadir mensajes a <code>ObservableList</code>, la tabla refleja la colección. Es información en memoria: desaparece cuando se cierra la aplicación.</div></div><div class="stack middle"><div class="panel"><div class="eyebrow">¿POR QUÉ NO JSON YA?</div><h3>No lo necesitamos para ver dos filas.</h3><p class="copy" style="margin-top:13px">El Controller crea temporalmente los mensajes: sirve para demostrar el enlace vista-datos. Lo separaremos cuando aparezcan registro, validación y persistencia.</p></div><div class="checkpoint">Prueba rápida: añade un tercer mensaje → 3 filas.</div></div></div>`,notes:'Importante señalar este trade-off: no es el Controller final ideal, es un estado transitorio consciente para introducir una sola idea a la vez. La persistencia aparecerá cuando haya un fallo visible de pérdida de datos.'}
,{section:'R02 · VALIDADO',title:'Dos mensajes visibles en JavaFX',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CHECKPOINT 02 · VALIDADO · 24 OCT 2026</div><h2>¡El modelo <span class="accent-green">se ve!</span></h2>${card('✓','Archivo FXML','La ventana contiene título, tabla y tres columnas.')}${card('✓','Controller','Lee las propiedades de cada MensajeFuturo desde la ObservableList.')}${card('✓','Resultado real','Dos filas: Valentina / 5 años; Carlos / 10 años.','green')}<div class="screenshot-note">Observación: el centrado de la ventana en el escritorio sigue siendo un detalle visual pendiente en WSL; no invalida el resultado funcional.</div></div>${img('25-tabla-mensajes-validada.webp','Ventana JavaFX real con dos mensajes y tres columnas')}</div>`,notes:'Captura final 13:13:10. No declarar persistentemente guardado nada: los dos mensajes se recrean en memoria al ejecutar. En la imagen se ven exactamente dos filas. El tema de centerOnScreen y VBox.alignment no debe consumir más tiempo de clase.'}
,{section:'PUENTE A R03',title:'Ahora quiero escribir mi propio mensaje',content:`<div class="hero-body"><div class="eyebrow">SIGUIENTE NECESIDAD · R03</div><h2>«No quiero depender de mensajes escritos en código: <span class="accent">quiero crear los míos</span>».</h2><p class="lead">Primero agregamos un formulario y un evento en <b>la misma vista</b>. No necesitamos todavía navegación entre FXML ni persistencia.</p><div class="lesson-row"><span class="lesson-chip">TextField</span><span class="lesson-chip">ComboBox</span><span class="lesson-chip">Button / onAction</span><span class="lesson-chip ghost-chip">aún sin JSON</span></div><div class="important">Criterio de aceptación: agregar una tercera fila y rechazar datos vacíos.</div></div>`,notes:'Este puente se planteó antes de R03. La implementación real mantuvo el formulario en la misma vista para evitar complicar el estado compartido. La navegación se reserva para R04.'}
,{section:'R03 · REQUERIMIENTO',title:'Ahora escribiré un mensaje desde la pantalla',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">RF-03 · NUEVA NECESIDAD</div><h2>«Quiero dejar un mensaje <span class="accent">sin editar el código</span>».</h2><p class="lead">Autor, texto y plazo de 1, 5 o 10 años. El nuevo mensaje debe aparecer en nuestra tabla.</p>${card('RF','Registrar en memoria','Desde la ventana, crear un MensajeFuturo y agregarlo a la lista observable.')}${card('RV','Validar entrada','No aceptar autor ni texto vacíos o compuestos solo por espacios.','green')}</div><div class="stack middle"><div class="panel"><div class="eyebrow">PRUEBAS DE ACEPTACIÓN</div><h3>Una fila nueva, no una pantalla nueva</h3><p class="copy" style="margin-top:12px">Dos filas iniciales → registro válido → tercera fila. Autor vacío → mensaje de error y sin nueva fila.</p></div><div class="important">Por ahora solo <b>una vista FXML</b>, datos en memoria. Navegación, Service y JSON llegarán al aparecer nuevas necesidades.</div></div></div>`,notes:'No anticipar pantallas adicionales: el requisito real de R03 es registrar desde la misma vista. Mantener las dos filas iniciales como referencia comparativa.'}
,{section:'R03 · TEORÍA',title:'¿Qué hace un botón al pulsarlo?',content:`<h2>La interfaz envía un <span class="accent">evento</span>, no guarda sola.</h2><div class="arrow-flow"><div class="flow-node">TextField + ComboBox<br><span class="small">entrada</span></div><span class="flow-arrow">→</span><div class="flow-node">onAction → Controller<br><span class="small">validación y creación</span></div><span class="flow-arrow">→</span><div class="flow-node">ObservableList<br><span class="small">tabla actualizada</span></div></div><div class="scalable-list" style="margin-top:22px">${card('1','TextField','Obtiene el nombre y el texto que escribió la persona.')}${card('2','ComboBox','Ofrece una elección cerrada: 1, 5 o 10 años.')}${card('3','Button','Dispara agregarMensaje() al hacer clic.')}</div><div class="screenshot-note">Implementación transitoria consciente: las reglas están hoy en HelloController. Luego las trasladaremos a Service para que no dependan de JavaFX.</div>`,notes:'Pregunta: ¿el Button crea objetos? No: llama un método del Controller. ¿Quién representa el mensaje? MensajeFuturo. ¿Quién refleja la nueva fila? La tabla enlazada a ObservableList.'}
,{section:'R03 · FXML',title:'Agregar el formulario sin borrar la tabla',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN · VISTA</div><h2>Un <span class="accent">HBox</span> sobre el TableView</h2>${code('hello-view.fxml · controles principales',`<HBox spacing="10" alignment="CENTER_LEFT">
  <TextField fx:id="campoAutor" promptText="Tu nombre"/>
  <TextField fx:id="campoTexto" promptText="Mensaje para el futuro"/>
  <ComboBox fx:id="campoPlazo"/>
  <Button text="Guardar mensaje"
          onAction="#agregarMensaje"/>
</HBox>
<Label fx:id="estadoRegistro" text=""/>`)}<div class="small">El texto «Guardar mensaje» es el rótulo actual del botón; <b>todavía significa agregar a memoria</b>, no guardar en disco.</div></div>${img('26-formulario-fxml.webp','HBox, TextField, ComboBox, botón y Label creados en el FXML')}</div>`,notes:'Captura 20:51:34. FXML se encarga de composición, fx:id y evento declarativo. No define reglas ni lee archivos.'}
,{section:'R03 · FXML ↔ JAVA',title:'Por qué coinciden los fx:id y los campos',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">INYECCIÓN DE CONTROLES</div><h2><span class="accent">@FXML</span> enlaza Java con el FXML.</h2>${code('HelloController.java · campos',`@FXML private TextField campoAutor;
@FXML private TextField campoTexto;
@FXML private ComboBox<Integer> campoPlazo;
@FXML private Label estadoRegistro;`)}${code('Al comienzo de initialize()',`campoPlazo.getItems().setAll(1, 5, 10);
campoPlazo.setValue(5);`)}<div class="small">El Controlador recibe referencias a los controles creados al cargar la vista. No está creando otra ventana.</div></div><div class="stack">${img('27-importaciones-controller.webp','Imports JavaFX de TextField, ComboBox y Label')}${img('28-campos-fxml-controller.webp','Campos @FXML preparados para inyección')}</div></div>`,notes:'Capturas 20:51:43 y 20:51:50. Si fx:id no coincide exactamente, el campo podría quedar null y disparar NullPointerException al accederlo.'}
,{section:'R03 · EVENTO',title:'Crear el objeto desde datos de pantalla',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">LÓGICA TEMPORAL DEL CONTROLADOR</div><h2>Validar → crear → <span class="accent">agregar</span></h2>${code('agregarMensaje() · núcleo',`String autor = campoAutor.getText().trim();
String texto = campoTexto.getText().trim();

if (autor.isBlank() || texto.isBlank()) {
    estadoRegistro.setText("Debes completar el autor y el mensaje.");
    return;
}

MensajeFuturo nuevo = new MensajeFuturo(
    autor, texto, campoPlazo.getValue());
mensajes.add(nuevo);`)}<div class="small">Después limpiamos campos, restablecemos el plazo y damos retroalimentación al usuario.</div></div>${img('29-evento-agregar-mensaje.webp','Implementación real del handler agregarMensaje y validación')}</div>`,notes:'Captura 20:52:08. Señalar que trim elimina espacios laterales y que isBlank detecta vacío. El return impide crear objeto inválido. Este control aún vive en Controller deliberadamente; lo moveremos a Service en R05.'}
,{section:'R03 · PRUEBA VÁLIDA',title:'La tabla se actualiza sin volver a cargar',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">ANTES / DESPUÉS</div><h2>¡Nuevo mensaje <span class="accent-green">visible!</span></h2>${card('1','Preparar','Completar Valentina + «Otro mensaje» + 10 años.')}${card('2','Accionar','Hacer clic en Guardar mensaje.')}${card('3','Comprobar','La lista pasa de tres a cuatro filas y muestra confirmación.','green')}<div class="screenshot-note">La captura de entrada y la de resultado fueron tomadas en la misma sesión: la app conserva sus registros <b>solo mientras está abierta</b>.</div></div><div class="stack">${img('30-formulario-completado.webp','Formulario con mensaje válido antes de registrar')}${img('31-registro-validado.webp','Ventana con cuatro mensajes y notificación de éxito')}</div></div>`,notes:'Capturas 20:52:50 y 20:52:56. El docente ya había agregado otro mensaje de prueba antes: no afirmar que la prueba pasó necesariamente de 2 a 3; se observa el aumento de 3 a 4.'}
,{section:'R03 · PRUEBA INVÁLIDA',title:'Un error del usuario no debe crear datos',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CHECKPOINT R03 · VALIDADO · 27 OCT 2026</div><h2>Sin autor ni texto: <span class="accent">rechazado.</span></h2>${card('✓','Validación','El código aplica trim() e isBlank() antes de construir el objeto.')}${card('✓','Interfaz','La aplicación muestra «Debes completar el autor y el mensaje».')}${card('✓','Resultado','En la captura no aparece una nueva fila por ese intento.','green')}<div class="important">Aún no hay persistencia. La etiqueta del botón dice «Guardar», pero el comportamiento de este incremento es <b>agregar a ObservableList</b>.</div></div>${img('32-validacion-campos-vacios.webp','Aviso real al intentar registrar campos vacíos')}</div>`,notes:'Captura 20:53:24. Verificación visual de rechazo de campos vacíos; la captura recortada no permite contar todas las filas, pero el flujo de código corta con return. No declarar implementada validación de todos los posibles datos fuera de estos casos.'}
,{section:'PUENTE A R04',title:'¿Y si el formulario necesita otra pantalla?',content:`<div class="hero-body"><div class="eyebrow">PRÓXIMO INCREMENTO · R04</div><h2>«La tabla crece… ¿podemos <span class="accent">separar el formulario</span> y volver sin perder los mensajes?»</h2><p class="lead">La necesidad de navegar entre vistas nos obligará a decidir <b>dónde vive el estado compartido</b> y cómo repartir responsabilidades.</p><div class="lesson-row"><span class="lesson-chip">Segunda vista FXML</span><span class="lesson-chip">FXMLLoader</span><span class="lesson-chip">Dos Controllers</span><span class="lesson-chip ghost-chip">aún sin JSON</span></div><div class="important">R04 ya fue implementado y validado; veamos ahora cómo navegamos sin perder los mensajes.</div></div>`,notes:'Dejar la navegación y el estado compartido para R04. Después refactorizar reglas a Service, añadir DAO y finalmente JSON cuando cerremos y perdamos la información. No confundir el botón Guardar con persistencia.'}

];
let current=0,showNotes=false;

const codeRepo="https://github.com/cmartinezs/DSY1102-JFX-TIME-CAPSULE";
const r05Branch="feat/dsy1102-r05-service";
const r05Code=(p)=>codeRepo+"/blob/"+r05Branch+"/"+p;
const r05Links=(entries)=>'<div class="source-files">'+entries.map(([label,path])=>'<a href="'+r05Code(path)+'" target="_blank" rel="noopener noreferrer">'+label+' ↗</a>').join('')+'</div>';

const sources={"R00":{"sha":"f3408276766358884c1c12f4c0b3ed63211bc36f","label":"Primera ventana JavaFX","files":[["pom.xml","pom.xml"],["HelloApplication.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloApplication.java"],["hello-view.fxml","src/main/resources/cl/duoc/dsy1102/timecapsule/hello-view.fxml"]]},"R01":{"sha":"13a21df0cfc536c0bcc016f2bae8f063058291dc","label":"Modelo y prueba en consola","files":[["MensajeFuturo.java","src/main/java/cl/duoc/dsy1102/timecapsule/model/MensajeFuturo.java"],["PruebaMensaje.java","src/main/java/cl/duoc/dsy1102/timecapsule/PruebaMensaje.java"]]},"R02":{"sha":"44511026ba156c4ed863ed45f987e4b7709b9179","label":"TableView y ObservableList","files":[["hello-view.fxml","src/main/resources/cl/duoc/dsy1102/timecapsule/hello-view.fxml"],["HelloController.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloController.java"],["HelloApplication.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloApplication.java"]]},"R03":{"sha":"ec77d7341973f21d14d29a437ba00c3adf9bd56c","label":"Formulario en una vista","files":[["hello-view.fxml","src/main/resources/cl/duoc/dsy1102/timecapsule/hello-view.fxml"],["HelloController.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloController.java"]]},"R04":{"sha":"09e5b99e9dce71998333f6c2718ff29040d9b00e","label":"Dos vistas y estado compartido","files":[["HelloApplication.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloApplication.java"],["HelloController.java","src/main/java/cl/duoc/dsy1102/timecapsule/HelloController.java"],["FormularioController.java","src/main/java/cl/duoc/dsy1102/timecapsule/FormularioController.java"],["hello-view.fxml","src/main/resources/cl/duoc/dsy1102/timecapsule/hello-view.fxml"],["formulario-view.fxml","src/main/resources/cl/duoc/dsy1102/timecapsule/formulario-view.fxml"]]}};
const urlFor=(stage,path)=>codeRepo+'/blob/'+sources[stage].sha+'/'+path;
const sourcePanel=stage=>{
 const s=sources[stage];
 return '<div class="source-panel"><div class="source-panel-header"><strong>'+stage+' · Código completo, versión fija</strong><span>commit <code>'+s.sha.slice(0,8)+'</code></span></div><p>Abre los archivos reales de este incremento, no los archivos cambiantes de master.</p><div class="source-files">'+s.files.map(([title,path])=>'<a href="'+urlFor(stage,path)+'" target="_blank" rel="noopener noreferrer">'+title+' ↗</a>').join('')+'</div><div class="source-actions"><a href="'+codeRepo+'/tree/'+s.sha+'" target="_blank" rel="noopener noreferrer">Proyecto completo ↗</a><a href="'+codeRepo+'/archive/'+s.sha+'.zip" target="_blank" rel="noopener noreferrer">Descargar código ZIP ↓</a></div></div>';
};
function addSourcesAfter(section,stage){
 const at=slides.findIndex(s=>s.section===section);
 if(at<0)throw new Error('Sección no encontrada: '+section);
 slides.splice(at+1,0,{section:stage+' · CÓDIGO COMPLETO',title:'Código completo y reproducible · '+stage,content:'<h2>El código completo está en un <span class="accent">commit fijo.</span></h2><p class="lead">'+sources[stage].label+'. Con el snapshot puedes compilar y explorar todas las clases del incremento, sin adelantar lo que viene.</p>'+sourcePanel(stage),notes:'Abrir los archivos del commit '+sources[stage].sha+'. El enlace a master no es una referencia histórica estable.'});
}
addSourcesAfter('CHECKPOINT 00 VALIDADO','R00');
addSourcesAfter('R01 · VALIDADO','R01');
addSourcesAfter('R02 · VALIDADO','R02');
addSourcesAfter('R03 · PRUEBA INVÁLIDA','R03');

// Las capturas R04 llegaron en orden inverso; se ordenaron por marca horaria real.
slides.push(
 {section:'R04 · NUEVO REQUERIMIENTO',title:'Separar pantallas sin perder mensajes',content:`<div class="grid2"><div class="stack"><div class="eyebrow">REQUERIMIENTO R04</div><h2>«El formulario debe tener su <span class="accent">propia pantalla</span>»</h2>${card('1','Listado','Muestra los mensajes y ofrece un botón para escribir uno nuevo.')}${card('2','Formulario','Captura autor, texto y plazo y permite guardar o cancelar.')}${card('3','Invariante','Cambiar de FXML no debe eliminar la lista que ya existe.','green')}<div class="important">Nuevo problema técnico: <b>cada carga de FXML crea un Controller nuevo</b>. ¿Dónde deben vivir entonces los mensajes?</div></div>${img('39-r04-listado-inicial.webp','Listado real con el botón Escribir nuevo mensaje')}</div>`,notes:'Estado comprobado 27-10. Aquí todavía NO hay persistencia a disco. Recurso completo en el commit R04.'},
 {section:'R04 · IDEA ARQUITECTÓNICA',title:'Una lista para dos controladores',content:`<div class="stack"><h2>La <span class="accent">ventana cambia</span>; los datos en memoria permanecen.</h2><div class="architecture-flow"><span>HelloApplication · ObservableList&lt;MensajeFuturo&gt;</span><strong>↓ configurar(this)</strong><div><span>HelloController · listado</span><span>FormularioController · formulario</span></div></div><p class="lead">La instancia de <code>HelloApplication</code> conserva la misma <code>ObservableList</code> y entrega acceso a los dos controladores.</p><div class="important">Es una <b>solución didáctica transitoria</b>, no el MVC final. Luego moveremos gestión y validaciones a un Service; hoy no inventamos capas que no necesitamos.</div></div>`,notes:'Explicar dependencia concreta del app context: controlador no crea listas, obtiene la lista compartida. Identificar acoplamiento pendiente para el Service.'},
 {section:'R04 · CÓDIGO NAVEGACIÓN',title:'¿Cómo cargamos otra pantalla?',content:`<div class="grid2 wide-image"><div class="stack"><h2>FXMLLoader + Controller + Scene</h2>${code('HelloApplication.java · flujo nuevo',`FXMLLoader loader = new FXMLLoader(\n    getClass().getResource("formulario-view.fxml")\n);\nParent root = loader.load();\nFormularioController controller = loader.getController();\ncontroller.configurar(this);\nstage.setScene(new Scene(root, 860, 480));`)}<p>Se reutiliza el mismo <code>Stage</code>. Lo que cambia es la <code>Scene</code>, cuyo contenido es la nueva vista FXML.</p><p><a href="${urlFor('R04','src/main/java/cl/duoc/dsy1102/timecapsule/HelloApplication.java')}" target="_blank" rel="noopener noreferrer">Abrir HelloApplication completo en R04 ↗</a></p></div>${img('35-r04-app-lista-compartida.webp','Lista de MensajeFuturo compartida desde HelloApplication')}</div>`,notes:'Enlace exacto al archivo real. No confundir Stage con VBox.alignment. Captura contiene variable mensajes y método getMensajes.'},
 {section:'R04 · LISTADO',title:'El listado deja de registrar',content:`<div class="grid2 wide-image"><div class="stack"><h2>Un controlador, <span class="accent">una responsabilidad visible.</span></h2>${code('HelloController.java · conexión de lista',`public void configurar(HelloApplication app) {\n    this.app = app;\n    tablaMensajes.setItems(app.getMensajes());\n}\n\n@FXML\nprivate void abrirFormulario() throws IOException {\n    app.mostrarFormulario();\n}`)}<p>El listado ya no conoce los TextField del formulario. Solamente muestra datos y solicita navegación.</p><p><a href="${urlFor('R04','src/main/java/cl/duoc/dsy1102/timecapsule/HelloController.java')}" target="_blank" rel="noopener noreferrer">Ver HelloController completo ↗</a></p></div>${img('36-r04-controller-listado.webp','HelloController conectado a la lista compartida')}</div>`,notes:'La captura corresponde al Controller de listado; el FXML original ya no contiene el formulario.'},
 {section:'R04 · SEGUNDA VISTA',title:'Formulario FXML con su Controller',content:`<div class="grid2"><div class="stack"><h2>El FXML <span class="accent">declara los controles</span>.</h2>${code('formulario-view.fxml · fragmento',`<VBox xmlns:fx="http://javafx.com/fxml/1"\n      fx:controller="cl.duoc.dsy1102.timecapsule.FormularioController">\n  <TextField fx:id="campoAutor" />\n  <TextField fx:id="campoTexto" />\n  <Button text="Guardar mensaje" onAction="#guardarMensaje" />\n  <Button text="Cancelar / Volver" onAction="#volver" />\n</VBox>`)}<div class="important">El XML de la vista debe coincidir con los <code>@FXML</code> y los métodos del Controller. El archivo completo incluye también el ComboBox del plazo y la etiqueta de aviso.</div><p><a href="${urlFor('R04','src/main/resources/cl/duoc/dsy1102/timecapsule/formulario-view.fxml')}" target="_blank" rel="noopener noreferrer">Abrir formulario-view.fxml completo ↗</a></p></div>${img('37-r04-formulario-xml.webp','Vista FXML del formulario y controles')}</div>`,notes:'Al crear otro FXML, un espacio antes de la declaración XML generó LoadException row 2 col 6. Caso real de diagnóstico, ya corregido en repositorio R04.'},
 {section:'R04 · REGISTRO',title:'El formulario envía el mensaje a la lista compartida',content:`<div class="grid2 wide-image"><div class="stack"><h2>Guardar significa <span class="accent">agregar en memoria</span>.</h2>${code('FormularioController.java · evento',`MenssageFuturo nuevo = new MensajeFuturo(\n    autor, texto, campoPlazo.getValue()\n);\napp.getMensajes().add(nuevo);\napp.mostrarListado();`.replace('MenssageFuturo','MensajeFuturo'))}<p>El formulario valida los campos, crea el objeto, agrega al estado compartido y regresa al listado. <b>No escribe JSON todavía.</b></p><p><a href="${urlFor('R04','src/main/java/cl/duoc/dsy1102/timecapsule/FormularioController.java')}" target="_blank" rel="noopener noreferrer">Ver FormularioController completo ↗</a></p></div>${img('41-r04-formulario-completado.webp','Formulario con Pedro, Un mensaje y plazo de un año')}</div>`,notes:'Evitar afirmar que controlador contiene toda la lógica de negocio: es implementación inicial. En próximo incremento extraer Service. Imagen del formulario completado anterior al guardado.'},
 {section:'R04 · ERROR REAL',title:'Un espacio puede romper la segunda pantalla',content:`<div class="grid2"><div class="stack"><div class="eyebrow">DIAGNÓSTICO DE AULA</div><h2>FXMLLoader falló al <span class="accent">abrir el formulario</span>.</h2>${code('Causa raíz · XMLStreamException',`ParseError at [row,col]: [2,6]\nThe processing instruction target matching\n"[xX][mM][lL]" is not allowed.`)}${card('1','Observar','El listado cargaba bien. El error apareció solo al pulsar el botón.')}${card('2','Localizar','La traza señalaba formulario-view.fxml, no hello-view.fxml.')}${card('3','Corregir','Eliminar el espacio inicial antes de <?xml ...?> y volver a ejecutar.','green')}</div>${img('37-r04-formulario-xml.webp','FXML válido sin contenido antes de la declaración XML')}</div>`,notes:'Hubo dos errores similares en dos vistas. Explicar cómo se llega al Caused by más profundo y al archivo correcto.'},
 {section:'R04 · CHECKPOINT',title:'Navegación y estado compartido comprobados',content:`<div class="grid2 wide-image"><div class="stack"><div class="eyebrow">R04 · VALIDACIÓN REAL</div><h2>Pedro sigue ahí <span class="accent">al volver al listado.</span></h2>${card('✓','Listado','Se observan Valentina y Carlos antes del registro.')}${card('✓','Formulario','Se abre una segunda vista con campos editables.')}${card('✓','Registro','Se ingresó Pedro / Un mensaje / 1 año y volvió a aparecer como tercera fila.','green')}<div class="important">Cierre con una prueba conceptual: <b>al cerrar y volver a iniciar la aplicación, la lista se reinicializa.</b> La persistencia llegará después de justificar su necesidad.</div></div>${img('42-r04-listado-final.webp','Tabla JavaFX con Pedro agregado después de volver desde el formulario')}</div>`,notes:'Evidencia visual real de tres filas. No declarar validada visualmente la prueba de reinicio sin captura; la pérdida se deduce de la lista inicializada en HelloApplication.'},
 {section:'R04 · CÓDIGO COMPLETO',title:'Reproduce R04 sin reconstruir capturas',content:`<h2>Tu proyecto, <span class="accent">congelado en R04.</span></h2><p class="lead">Todos los Java, FXML, el pom.xml y el module-info.java están disponibles juntos, en el mismo commit.</p>${sourcePanel('R04')}<div class="screenshot-note">Ruta de clase: el proyecto <b>DSY1102-JFX-TIME-CAPSULE</b> es distinto del repositorio de materiales DSY1102.</div>`,notes:'Abrir el commit 09e5b99e. Es el estado completo después de la navegación y sin DAO/JSON.'},
 {section:'PUENTE A R05',title:'¿Dónde ponemos las reglas de negocio?',content:`<div class="hero-body"><div class="eyebrow">SIGUIENTE INCREMENTO · R05</div><h2>«Validar mensajes desde la pantalla funciona, pero…<br><span class="accent">¿quién debería decidir las reglas?</span>»</h2><p class="lead">Extraeremos un Service pequeño para que el Controller se ocupe de la interacción y no concentre las reglas del dominio.</p><div class="lesson-row"><span class="lesson-chip">Responsabilidad única</span><span class="lesson-chip">Service</span><span class="lesson-chip ghost-chip">DAO/JSON después</span></div></div>`,notes:'R05 no está implementado. No crear un DAO solo por imponer capas; primero Service para reglas y gestión, luego persistencia para resolver pérdida tras reinicio.'}
);

const r05Base='src/main/java/cl/duoc/dsy1102/timecapsule/';
const r05StageFiles=[
 ['MensajeService.java',r05Base+'service/MensajeService.java'],
 ['MensajeDao.java',r05Base+'dao/MensajeDao.java'],
 ['JsonMensajeDao.java',r05Base+'dao/JsonMensajeDao.java'],
 ['MensajeFuturo.java',r05Base+'model/MensajeFuturo.java'],
 ['HelloApplication.java',r05Base+'HelloApplication.java'],
 ['FormularioController.java',r05Base+'FormularioController.java'],
 ['pom.xml','pom.xml'],
 ['module-info.java','src/main/java/module-info.java']
];
slides.push(
{section:'R05 · NECESIDAD',title:'¿Y si cerramos la cápsula?',content:`<div class="grid2"><div class="stack middle"><div class="eyebrow">REQUERIMIENTO NUEVO · R05</div><h2>«Escribí mis mensajes… ¿por qué <span class="accent">desaparecen al cerrar</span>?»</h2><p class="lead">R04 conserva datos entre pantallas, no entre ejecuciones. Ahora necesitamos guardar en disco sin mezclar FXML, reglas y archivos.</p>${card('RF','Persistir','Los mensajes válidos deben conservarse en un JSON.')}${card('RT','Separar','Controller → Service → DAO → JSON.','green')}</div><div class="stack middle">${img('r05-05.webp','Primera ejecución con tabla vacía y sin archivo previo')}<div class="screenshot-note">Captura docente de R05: el primer inicio sin archivo JSON muestra una tabla vacía. No se insertan ejemplos ficticios automáticamente.</div></div></div>`,notes:'Contrastar estado entre vistas de R04 con persistencia en disco de R05. Al principio el JSON puede no existir; no es un error.'},
{section:'R05 · DISEÑO',title:'Separar responsabilidades antes de persistir',content:`<h2>Cuatro decisiones, <span class="accent">cuatro responsabilidades.</span></h2><div class="scalable-list">${card('1','FXML + Controller','Reciben entradas, navegan y muestran mensajes.')}${card('2','MensajeService','Valida el registro y coordina guardar.')}${card('3','MensajeDao + JSON','Decide cómo leer/escribir los datos en disco.','green')}</div><div class="important">El Controller no manipula archivos. El Service no importa JavaFX. La implementación DAO no decide reglas de negocio.</div>${r05Links([['MensajeService',r05Base+'service/MensajeService.java'],['MensajeDao',r05Base+'dao/MensajeDao.java'],['JsonMensajeDao',r05Base+'dao/JsonMensajeDao.java']])}`,notes:'Pedir que identifiquen qué clase cambiaríamos si mañana el almacenamiento fuera relacional. No presentar JDBC como implementado.'},
{section:'R05 · SERVICE',title:'La lógica ya no vive en el formulario',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">REFAC / CÓDIGO REAL</div><h2>MensajeService recibe <span class="accent">un DAO.</span></h2>${code('MensajeService · constructor y persistencia', 'public MensajeService(MensajeDao dao) throws IOException {\n    this.dao = dao;\n    this.mensajes = new ArrayList<>(dao.listar());\n}\n\n// Dentro de registrar(...):\ndao.guardar(actualizados);\nmensajes.add(nuevo);') }<p class="copy">El Service valida y ordena guardar. Solo agrega a memoria cuando la escritura concluye.</p>${r05Links([['Código completo',r05Base+'service/MensajeService.java']])}</div>${img('r05-02.webp','MensajeService: validaciones y dao.guardar(actualizados)')}</div>`,notes:'Captura docente muestra el servicio real. Señalar que si guardar falla la memoria no incorpora el mensaje; la escritura directa del DAO no es atómica todavía.'},
{section:'R05 · CONTRATO DAO',title:'¿Qué necesitamos saber del almacenamiento?',content:`<h2>Un contrato pequeño para <span class="accent">leer y guardar.</span></h2>${code('MensajeDao.java · interfaz completa','package cl.duoc.dsy1102.timecapsule.dao;\n\nimport cl.duoc.dsy1102.timecapsule.model.MensajeFuturo;\nimport java.io.IOException;\nimport java.util.List;\n\npublic interface MensajeDao {\n    List<MensajeFuturo> listar() throws IOException;\n    void guardar(List<MensajeFuturo> mensajes) throws IOException;\n}') }<p class="lead">El contrato habla de mensajes, no de rutas ni de una biblioteca específica.</p>${r05Links([['MensajeDao.java completo',r05Base+'dao/MensajeDao.java']])}`,notes:'Preguntar: ¿por qué declarar IOException? Comparar contrato con implementación. La interfaz DAO no contiene lógica de JSON.'},
{section:'R05 · TESTS MAVEN',title:'El proyecto también necesita pruebas ejecutables',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CONFIGURACIÓN DE PRUEBAS</div><h2>JUnit 5 se ejecuta con <span class="accent">Maven Surefire.</span></h2>${code('pom.xml · plugin de pruebas','<plugin>\n  <groupId>org.apache.maven.plugins</groupId>\n  <artifactId>maven-surefire-plugin</artifactId>\n  <version>3.2.5</version>\n</plugin>')}<p class="copy">Fijar el runner ayuda a ejecutar las pruebas del Service y del DAO de forma reproducible. La captura del POM muestra el plugin, no el resultado de un test.</p>${r05Links([['pom.xml','pom.xml'],['Test Service','src/test/java/cl/duoc/dsy1102/timecapsule/service/MensajeServiceTest.java'],['Test DAO','src/test/java/cl/duoc/dsy1102/timecapsule/dao/JsonMensajeDaoTest.java']])}</div>${img('r05-03.webp','Configuración del plugin Maven Surefire')}</div>`,notes:'Diferenciar tener tests escritos y haberlos ejecutado. No declarar mvn test exitoso sin salida de ejecución.'},
{section:'R05 · JACKSON',title:'Maven incorpora la biblioteca de JSON',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">DEPENDENCIA + SEGURIDAD</div><h2>Jackson transforma <span class="accent">objetos ⇄ JSON.</span></h2>${code('pom.xml · dependencia', '<dependency>\n    <groupId>com.fasterxml.jackson.core</groupId>\n    <artifactId>jackson-databind</artifactId>\n    <version>2.22.4</version>\n</dependency>')}<div class="screenshot-note">La captura docente muestra actualización a <b>2.22.4</b> por una advertencia de vulnerabilidad. Antes de reproducir el código, verificar que esta versión esté efectivamente en la rama que se va a ejecutar.</div>${r05Links([['pom.xml actual de la rama','pom.xml'],['module-info.java','src/main/java/module-info.java']])}</div>${img('r05-04.webp','Dependencia Jackson actualizada en pom.xml a 2.22.4')}</div>`,notes:'La captura muestra la versión 2.22.4 elegida por el docente. El enlace apunta a la rama de trabajo, que puede no estar sincronizada hasta hacer commit/push. No certificar la resolución de CVE sin un escaneo.'},
{section:'R05 · DAO JSON',title:'Del objeto Java al archivo JSON',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">IMPLEMENTACIÓN · OBJECTMAPPER</div><h2><span class="accent">JsonMensajeDao</span> conoce el archivo.</h2>${code('JsonMensajeDao · métodos centrales','if (Files.notExists(archivo)) {\n    return List.of();\n}\nreturn mapper.readValue(archivo.toFile(),\n    new TypeReference<List<MensajeFuturo>>() {});\n\n// Para guardar:\nmapper.writerWithDefaultPrettyPrinter()\n      .writeValue(archivo.toFile(), mensajes);')}<p class="copy">El archivo ausente significa lista vacía. Un archivo malformado produce error: no debe sobrescribirse silenciosamente.</p>${r05Links([['JsonMensajeDao.java completo',r05Base+'dao/JsonMensajeDao.java']])}</div>${img('r05-01.webp','Implementación de JsonMensajeDao en IntelliJ')}</div>`,notes:'Señalar que el DAO es quien conoce Path, ObjectMapper y la ruta local. La escritura directa se mejorará como parte de R06.'},
{section:'R05 · SERIALIZACIÓN',title:'El modelo también debe poder reconstruirse',content:`<h2>Jackson necesita <span class="accent">crear el objeto al leer.</span></h2>${code('MensajeFuturo.java · añadidos de R05','public MensajeFuturo() { }\n\npublic void setAutor(String autor) { this.autor = autor; }\npublic void setTexto(String texto) { this.texto = texto; }\npublic void setPlazoAnios(int plazoAnios) { this.plazoAnios = plazoAnios; }')}<p class="lead">Conservamos constructor y getters de R01. Agregamos constructor vacío y setters para la deserialización con esta configuración.</p>${r05Links([['Modelo completo',r05Base+'model/MensajeFuturo.java'],['Configuración modular','src/main/java/module-info.java']])}`,notes:'Explicar serializar vs deserializar con los campos autor/texto/plazoAnios. Los setters son una solución didáctica compatible con la configuración actual.'},
{section:'R05 · PRIMER REGISTRO',title:'Antes de guardar, el JSON no existe',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PRUEBA REAL · FORMULARIO</div><h2>Escribimos un <span class="accent">primer mensaje.</span></h2>${card('1','Autor','Carlos')}${card('2','Texto','Mensaje de prueba')}${card('3','Plazo','5 años')}<div class="important">Al pulsar Guardar, el Controller llama al Service. El DAO escribe el archivo; la vista vuelve al listado.</div></div>${img('r05-06.webp','Formulario con primer mensaje de prueba')}</div>`,notes:'Captura real aportada por el docente. Mantener nombres y datos tal como se ven; no sustituir por Ana, que fue solo un dato sugerido antes.'},
{section:'R05 · RESULTADO',title:'El mensaje aparece en la tabla',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CHECKPOINT VISUAL 01</div><h2>¡Carlos aparece <span class="accent-green">en el listado!</span></h2><p class="lead">Autor: Carlos · Texto: Mensaje de prueba · Plazo: 5 años.</p><div class="checkpoint">✓ La interfaz confirma el resultado del registro.</div><div class="screenshot-note">La fila visible, por sí sola, no demuestra persistencia. Debemos observar el JSON generado.</div></div>${img('r05-07.webp','Listado con el primer mensaje guardado')}</div>`,notes:'Relacionar lo que aparece en TableView con el objeto guardado, evitando confundir UI con almacenamiento.'},
{section:'R05 · JSON GENERADO',title:'Ahora existe un archivo que conserva los datos',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">CHECKPOINT 02 · ARCHIVO REAL</div><h2><span class="accent">data/mensajes.json</span></h2>${code('Archivo generado','[\n  {\n    "autor": "Carlos",\n    "texto": "Mensaje de prueba",\n    "plazoAnios": 5\n  }\n]')}<p class="copy">El archivo se crea en una carpeta <code>data/</code> relativa al directorio de trabajo de la aplicación.</p></div>${img('r05-08.webp','JSON real con un registro Carlos')}</div>`,notes:'Mostrar que JSON es texto estructurado legible. Señalar que data/ se excluye de Git para evitar versionar datos de ejecución.'},
{section:'R05 · SEGUNDA ALTA',title:'¿Qué ocurre al registrar otro mensaje?',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">PRUEBA DE INTEGRACIÓN</div><h2>Un segundo mensaje <span class="accent">sin perder el primero.</span></h2>${card('1','Autor','Carlos')}${card('2','Texto','Otro Mensaje')}${card('3','Plazo','5 años')}<p class="copy">El Service prepara una colección con los datos existentes y el nuevo mensaje. El DAO vuelve a escribir el contenido completo.</p></div>${img('r05-09.webp','Formulario con segundo mensaje')}</div>`,notes:'Comprobar que se conservan los mensajes existentes. Aquí aún no se evalúa simultaneidad ni escritura atómica.'},
{section:'R05 · DOS REGISTROS',title:'Dos filas en la interfaz, dos objetos en JSON',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">EVIDENCIA CONJUNTA</div><h2>La interfaz y el archivo <span class="accent-green">coinciden.</span></h2><p class="lead">La tabla presenta «Mensaje de prueba» y «Otro Mensaje», ambos de Carlos con plazo de 5 años.</p><div class="checkpoint">✓ La segunda alta no borra la primera.</div></div>${img('r05-10.webp','Tabla con los dos mensajes de Carlos')}</div>`,notes:'Captura real. Para demostrar que persiste entre ejecuciones necesitamos reiniciar la aplicación y observar la recuperación; si no hay captura de reinicio, no marcar esa prueba como realizada.'},
{section:'R05 · JSON FINAL',title:'La colección fue serializada completa',content:`<div class="grid2 wide-image"><div class="stack middle"><div class="eyebrow">EVIDENCIA REAL EN DISCO</div><h2>El JSON ya contiene <span class="accent">dos mensajes.</span></h2>${code('data/mensajes.json · comprobado','[\n  {"autor":"Carlos","texto":"Mensaje de prueba","plazoAnios":5},\n  {"autor":"Carlos","texto":"Otro Mensaje","plazoAnios":5}\n]')}<p class="copy">Jackson escribió ambos objetos. La captura muestra el archivo abierto en IntelliJ después de la segunda alta.</p></div>${img('r05-11.webp','Archivo JSON con dos mensajes persistidos')}</div>`,notes:'Importante: esta evidencia acredita escritura, no necesariamente un reinicio exitoso. No atribuir pruebas de recuperación que no se capturaron.'},
{section:'R05 · CHEQUEO',title:'¿Qué aprendimos y qué falta comprobar?',content:`<h2>De una lista temporal a <span class="accent">persistencia real.</span></h2><div class="scalable-list">${card('✓','Separación','Controllers → Service → DAO.')}${card('✓','Guardar','Archivo JSON con dos registros, comprobado visualmente.')}${card('?','Recuperar','Cerrar y ejecutar de nuevo: verificar que ambos regresan.','orange')}</div><div class="important">Pendiente de validación en R06: archivo malformado, respaldo, recuperación y comportamiento ante escritura fallida.</div>${r05Links([['Pruebas del Service','src/test/java/cl/duoc/dsy1102/timecapsule/service/MensajeServiceTest.java'],['Pruebas del DAO','src/test/java/cl/duoc/dsy1102/timecapsule/dao/JsonMensajeDaoTest.java']])}`,notes:'No declarar mvn test exitoso porque las capturas aportadas no incluyen reporte de ejecución de tests. Estado evidenciado: interfaz y escritura JSON.'},
{section:'R05 · CÓDIGO COMPLETO',title:'Explorar todos los archivos de R05',content:`<h2><span class="accent">Código reproducible,</span> por responsabilidad.</h2><p class="lead">Abre cada archivo de la rama R05. Cuando se cierre la validación se fijará un commit exacto como snapshot histórico.</p>${r05Links(r05StageFiles)}<div class="source-actions"><a href="${codeRepo}/tree/${r05Branch}" target="_blank" rel="noopener noreferrer">Abrir proyecto R05 completo ↗</a><a href="${codeRepo}/archive/refs/heads/${r05Branch}.zip" target="_blank" rel="noopener noreferrer">ZIP de la rama R05 ↗</a></div><div class="screenshot-note">No fusionar al histórico de clases hasta conciliar el POM actualizado por seguridad y las pruebas de ejecución.</div>`,notes:'Los enlaces de R05 apuntan a una rama en trabajo, no a commit congelado. Revisar seguridad de dependencias antes de crear el snapshot definitivo.'},
{section:'PUENTE A R06',title:'¿Qué pasa si el JSON se daña?',content:`<h2>Guardar funcionó. Pero… <span class="accent">¿podemos confiar en el archivo?</span></h2><p class="lead">R06 comprobará reinicio, recuperación, datos malformados, tratamiento seguro de fallos y una estrategia de respaldo.</p><div class="lesson-row"><span class="lesson-chip">Deserialización</span><span class="lesson-chip">Reinicio</span><span class="lesson-chip">JSON malformado</span><span class="lesson-chip">Respaldo</span></div>`,notes:'R06 se mantiene separado. No enseñar manejo avanzado de fallos como ya implementado si no hay pruebas evidenciadas.'}
);

let stageActive='R00';
for(const s of slides){const m=s.section.match(/^R0[1-5] ·/);if(m)stageActive=m[0].slice(0,3);s.stage=stageActive;}
function sourceFooter(stage){if(stage==='R05')return '<div class="source-footer"><span>R05 · rama en validación</span><a href="'+codeRepo+'/tree/'+r05Branch+'" target="_blank" rel="noopener noreferrer">Código R05 completo ↗</a></div>';const s=sources[stage];return '<div class="source-footer"><span>'+stage+' · commit '+s.sha.slice(0,8)+'</span><a href="'+codeRepo+'/tree/'+s.sha+'" target="_blank" rel="noopener noreferrer">Código completo de esta etapa ↗</a></div>';}

const el=id=>document.getElementById(id);
function render(){const item=slides[current];const body=item.content;el('slide').innerHTML=`<div class="eyebrow">${item.section}</div>${body}${sourceFooter(item.stage)}<aside class="speaker"><strong>NOTA DOCENTE:</strong> ${item.notes}</aside>`;el('slide').classList.toggle('show-notes',showNotes);el('slide').scrollTop=0;el('slide-index').textContent=String(current+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');el('slide-section').textContent=item.section;el('progress').style.width=`${(current+1)/slides.length*100}%`;el('previous').disabled=current===0;el('next').disabled=current===slides.length-1;document.title=`${current+1}/${slides.length} · ${item.title} · DSY1102`;history.replaceState(null,'',`#${current+1}`);el('slide').querySelectorAll('img').forEach(i=>{i.addEventListener('error',()=>{const fig=i.closest('.picture');const layout=fig?.parentElement;if(layout?.classList.contains('grid2'))layout.classList.add('no-image');fig?.remove();});i.addEventListener('click',()=>{if(i.closest('.picture').classList.contains('broken'))return;el('image-enlarged').src=i.src;el('image-title').textContent=i.alt;el('image-lightbox').showModal();});});el('slide').querySelectorAll('.copy-code').forEach(b=>b.addEventListener('click',async()=>{const s=b.closest('.codebox').querySelector('code').textContent;try{await navigator.clipboard.writeText(s);b.textContent='Copiado ✓';setTimeout(()=>b.textContent='Copiar código',1400)}catch(e){b.textContent='Selecciona y copia'}}));}
function go(n){if(n<0||n>=slides.length)return;current=n;render();}
function buildOverview(){el('overview-grid').innerHTML=slides.map((s,i)=>`<button data-target="${i}"><span>${String(i+1).padStart(2,'0')} · ${s.section}</span>${s.title}</button>`).join('');el('overview-grid').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{go(Number(b.dataset.target));el('overview').close()}));}
el('previous').onclick=()=>go(current-1);el('next').onclick=()=>go(current+1);el('notes-toggle').onclick=()=>{showNotes=!showNotes;render()};el('overview-toggle').onclick=()=>el('overview').showModal();el('close-overview').onclick=()=>el('overview').close();el('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.();el('close-image').onclick=()=>el('image-lightbox').close();document.addEventListener('keydown',e=>{const dialogOpen=el('overview').open||el('image-lightbox').open;if(dialogOpen)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key.toLowerCase()==='n'){showNotes=!showNotes;render()}if(e.key.toLowerCase()==='g'){el('overview').showModal()}if(e.key.toLowerCase()==='f'){document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen?.()}});window.addEventListener('hashchange',()=>{let n=parseInt(location.hash.slice(1),10);if(Number.isInteger(n)&&n>=1&&n<=slides.length&&n-1!==current)go(n-1)});buildOverview();const start=parseInt(location.hash.slice(1),10);current=Number.isInteger(start)?Math.max(0,Math.min(slides.length-1,start-1)):0;render();
